# Lernvideo 04 v2 – erzeugt von gen.py
S = [('Übung 2 Schritt für Schritt', [('Übung 2: *Matrizen invertieren* und *Gleichungssysteme* lösen.', 'In Übung zwei geht es darum, Matrizen zu invertieren und Gleichungssysteme zu lösen.'), ('Zuerst der *komplette Weg* an einem ausführlichen Beispiel.', 'Zuerst rechnen wir den kompletten Weg an einem ausführlichen Beispiel durch, jeden Schritt einzeln.'), ('Danach jede Aufgabe – mit dem *kürzesten* Rechenweg.', 'Danach kommt jede Aufgabe der Übung dran, jeweils mit dem kürzesten Rechenweg.'), ('Die *Aufgabenstellung* bleibt dabei immer oben stehen.', 'Die Aufgabenstellung bleibt dabei immer oben eingeblendet, damit du jede Zahl nachrechnen kannst.')]), ('Beispiel: der komplette Weg', [('Beispiel: A ist *nicht symmetrisch* und hat *Minuszeichen*.', 'Unser Beispiel ist diese Matrix A. Sie ist nicht symmetrisch und hat Minuszeichen. Genau da passieren die typischen Fehler.'), ('Ziel: *A⁻¹* – die Matrix mit *A · A⁻¹ = I*.', 'Gesucht ist die Inverse, also die Matrix, die mit A multipliziert die Einheitsmatrix ergibt.'), ('Formel: *A⁻¹ = C′ / det A*', 'Die Formel dafür: Inverse gleich transponierte Kofaktormatrix, geteilt durch die Determinante.'), ('Fünf Schritte – und am Schluss die *Probe*.', 'Das sind fünf Schritte: Determinante, Minoren, Vorzeichen, transponieren, teilen. Und am Schluss die Probe.')]), ('Beispiel · Schritt 1: det A', [('Sarrus: Spalte 1 und 2 *rechts daneben* schreiben.', 'Schritt eins ist die Determinante. Für drei mal drei nimmst du die Regel von Sarrus: Schreib die ersten zwei Spalten noch einmal rechts daneben.'), ('↘ blau: 2·0·(−3) = 0 · (−1)·4·(−2) = 8 · 2·1·1 = 2 → *10*', 'Jetzt die drei blauen Diagonalen nach rechts unten. Zwei mal null mal minus drei ist null. Minus eins mal vier mal minus zwei ist plus acht, denn zwei Minus ergeben plus. Zwei mal eins mal eins ist zwei. Zusammen zehn.'), ('↙ orange: 2·0·(−2) = 0 · 2·4·1 = 8 · (−1)·1·(−3) = 3 → *11*', 'Dann die drei orangen Diagonalen nach links unten. Zwei mal null mal minus zwei ist null. Zwei mal vier mal eins ist acht. Minus eins mal eins mal minus drei ist drei. Zusammen elf.'), ('det A = blau − orange = 10 − 11 = *−1 ≠ 0* → A⁻¹ *existiert*.', 'Die Determinante ist blau minus orange: zehn minus elf, also minus eins. Nicht null, also gibt es eine Inverse.')]), ('Beispiel · Schritt 2 und 3: Kofaktoren, Zeile 1', [('Jeder Eintrag c_ij von C bekommt eine *eigene kleine Rechnung*.', 'Jetzt kommt die Kofaktormatrix C. Jeder ihrer neun Einträge bekommt eine eigene kleine Rechnung.'), ('c₁₁: *Zeile 1* und *Spalte 1* abdecken.', 'Für c eins eins deckst du Zeile eins und Spalte eins ab. Die beiden Indizes sagen dir, welche Zeile und welche Spalte.'), ('Übrig bleibt eine 2×2-Matrix aus *0, 4, 1, −3*.', 'Übrig bleiben vier Zahlen: null und vier oben, eins und minus drei unten. Das ist eine kleine zwei mal zwei Matrix.'), ('Minor m₁₁ = *0·(−3)* − *4·1* = 0 − 4 = *−4*', 'Davon die Determinante: die blaue Diagonale, null mal minus drei, minus die orange Diagonale, vier mal eins. Null minus vier ist minus vier. Das ist der Minor.'), ('Schachbrett oben links: *+* → c₁₁ = *−4*', 'Das Vorzeichen kommt aus dem Schachbrett. Oben links steht plus. Also bleibt es bei minus vier, und das kommt in C oben links.'), ('Schachbrett = (−1)^(i+j): i+j *gerade* → +, *ungerade* → −', 'Das Schachbrett ist nichts anderes als minus eins hoch i plus j. Ist i plus j gerade, steht dort plus. Ist die Summe ungerade, minus.'), ('c₁₂: Zeile 1 und *Spalte 2* weg → übrig *1, 4, −2, −3*', 'Weiter mit c eins zwei: Zeile eins und Spalte zwei weg. Übrig bleiben eins und vier, darunter minus zwei und minus drei.'), ('m₁₂ = 1·(−3) − 4·(−2) = −3 + 8 = 5 · Schachbrett *−* → c₁₂ = *−5*', 'Blau: eins mal minus drei ist minus drei. Orange: vier mal minus zwei ist minus acht. Minus drei minus minus acht ist plus fünf. Das Schachbrett sagt hier minus, also ist c eins zwei minus fünf.'), ('c₁₃: 1·1 − 0·(−2) = 1 · Schachbrett + → *1*', 'c eins drei: Zeile eins und Spalte drei weg. Blau eins mal eins, orange null mal minus zwei. Das ergibt eins, Vorzeichen plus, also eins.')]), ('Beispiel · Kofaktoren, Zeile 2', [('c₂₁: Zeile 2, Spalte 1 weg → (−1)·(−3) − 2·1 = 1 · Schachbrett *−* → *−1*', 'Zeile zwei. Für c zwei eins deckst du Zeile zwei und Spalte eins ab. Blau: minus eins mal minus drei ist drei. Orange: zwei mal eins ist zwei. Drei minus zwei ist eins. In Zeile zwei beginnt das Schachbrett mit minus, also minus eins.'), ('c₂₂: 2·(−3) − 2·(−2) = −6 + 4 = −2 · Schachbrett + → *−2*', 'c zwei zwei: Zeile zwei und Spalte zwei weg. Zwei mal minus drei ist minus sechs. Zwei mal minus zwei ist minus vier, und das wird abgezogen. Minus sechs plus vier ist minus zwei. Vorzeichen plus, es bleibt minus zwei.'), ('c₂₃: 2·1 − (−1)·(−2) = 2 − 2 = 0 → *0*', 'c zwei drei: Zeile zwei und Spalte drei weg. Zwei mal eins ist zwei. Minus eins mal minus zwei ist auch zwei. Zwei minus zwei ist null, und null bleibt null, egal welches Vorzeichen.'), ('Das Vorzeichen hängt *nur von der Position* ab – nicht vom Minor.', 'Wichtig: Das Vorzeichen hängt nur von der Position ab, nicht davon, ob der Minor schon negativ ist.')]), ('Beispiel · Kofaktoren, Zeile 3', [('c₃₁: Zeile 3, Spalte 1 weg → (−1)·4 − 2·0 = −4 · Schachbrett + → *−4*', 'Zeile drei. c drei eins: Zeile drei und Spalte eins weg. Minus eins mal vier ist minus vier, zwei mal null ist null. Der Minor ist minus vier, Vorzeichen plus, also minus vier.'), ('c₃₂: 2·4 − 2·1 = 8 − 2 = 6 · Schachbrett *−* → *−6*', 'c drei zwei: Spalte zwei weg. Zwei mal vier ist acht, zwei mal eins ist zwei. Acht minus zwei ist sechs. Vorzeichen minus, also minus sechs.'), ('c₃₃: 2·0 − (−1)·1 = 0 + 1 = 1 · Schachbrett + → *1*', 'c drei drei: Spalte drei weg. Zwei mal null ist null, minus eins mal eins ist minus eins. Null minus minus eins ist plus eins. Vorzeichen plus, also eins.'), ('C ist komplett: *neun* Minoren, *neun* Vorzeichen.', 'Damit ist die Kofaktormatrix komplett: neun Minoren und neun Vorzeichen.')]), ('Beispiel · Schritt 4: transponieren', [('C′: *Zeile 1* von C wird *Spalte 1* von C′ – Zeile 2 → Spalte 2 – Zeile 3 → Spalte 3', 'Schritt vier: transponieren. Die erste Zeile von C wird die erste Spalte von C strich. Dann die zweite Zeile zur zweiten Spalte, und die dritte zur dritten.'), ('Die *Diagonale* bleibt, der Rest wird an ihr *gespiegelt*.', 'Die Diagonale bleibt stehen, alles andere wird an ihr gespiegelt. Zum Beispiel wandert die minus fünf aus Zeile eins, Spalte zwei nach Zeile zwei, Spalte eins.'), ('Ohne Transponieren wäre A · A⁻¹ *nicht* I – bei nicht symmetrischem A.', 'Warum das Ganze? Nur mit der transponierten Kofaktormatrix ergibt A mal Inverse die Einheitsmatrix. Bei nicht symmetrischen Matrizen wäre es ohne Transponieren falsch.')]), ('Beispiel · Schritt 5: teilen und Probe', [('A⁻¹ = C′ / (−1): durch −1 teilen = *jedes Vorzeichen umdrehen*.', 'Schritt fünf: durch die Determinante teilen. Teilen durch minus eins heißt einfach: Jedes Vorzeichen dreht sich um.'), ('Probe mit A: Zeile 1 · Spalte 1 = 2·4 + (−1)·5 + 2·(−1) = 8 − 5 − 2 = *1* ✓', 'Jetzt die Probe, mit A unten eingeblendet. Zeile eins von A mal Spalte eins der Inversen: zwei mal vier ist acht, minus eins mal fünf ist minus fünf, zwei mal minus eins ist minus zwei. Acht minus fünf minus zwei ist eins. Genau die Eins der Einheitsmatrix.'), ('Zeile 1 · Spalte 2 = 2·1 + (−1)·2 + 2·0 = *0* ✓', 'Zeile eins mal Spalte zwei: zwei mal eins, minus eins mal zwei, zwei mal null. Zwei minus zwei ist null. Auch richtig.'), ('Zeile 2 · Spalte 2 = 1·1 + 0·2 + 4·0 = *1* ✓', 'Zeile zwei mal Spalte zwei: eins mal eins, null mal zwei, vier mal null. Das ergibt eins.'), ('Alle neun Einträge so → *A · A⁻¹ = I* ✓', 'So ergibt jede Kombination eins auf der Diagonale und null daneben. Damit ist die Inverse bestätigt.')]), ('Aufgabe 1: die Aufgabenstellung', [('Aufgabe 1: *drei Teile* – genau die Schritte aus dem Beispiel.', 'Aufgabe eins hat drei Teile, genau die Schritte aus dem Beispiel.'), ('A) det A – *regulär* heißt nur: *det A ≠ 0*.', 'Teil a: die Determinante, und ob A regulär ist. Regulär heißt nur: Die Determinante ist nicht null.'), ('B) Kofaktormatrix C · C) A⁻¹ = C′ / det A', 'Teil b ist die Kofaktormatrix, Teil c die Inverse über die Formel.'), ('Auffällig: A ist *symmetrisch* – das spart Arbeit.', 'Schau dir A genau an: Sie ist symmetrisch zur Diagonale. Das spart gleich Arbeit.')]), ('Aufgabe 1 A: die Determinante', [('↘ blau: 3·4·3 = 36 · 2·2·1 = 4 · 1·2·2 = 4 → *44*', 'Sarrus wie im Beispiel. Blau nach rechts unten: drei mal vier mal drei ist sechsunddreißig, zwei mal zwei mal eins ist vier, eins mal zwei mal zwei ist vier. Zusammen vierundvierzig.'), ('↙ orange: 1·4·1 = 4 · 3·2·2 = 12 · 2·2·3 = 12 → *28*', 'Orange nach links unten: eins mal vier mal eins ist vier, drei mal zwei mal zwei ist zwölf, zwei mal zwei mal drei ist zwölf. Zusammen achtundzwanzig.'), ('det A = 44 − 28 = *16 ≠ 0* → A ist *regulär*.', 'Vierundvierzig minus achtundzwanzig ist sechzehn. Nicht null, also ist A regulär. Das ist Teil a.')]), ('Aufgabe 1 B: die Kofaktormatrix', [('B) A symmetrisch → *C symmetrisch*: nur 6 Einträge rechnen.', 'Teil b. Weil A symmetrisch ist, wird auch C symmetrisch. Es reichen die sechs Einträge auf und über der Diagonale.'), ('c₁₁: Zeile 1, Spalte 1 weg → 4·3 − 2·2 = 8 · Schachbrett + → *8*', 'c eins eins: vier mal drei, minus zwei mal zwei, ist acht. Vorzeichen plus: acht.'), ('c₁₂: Zeile 1, Spalte 2 weg → 2·3 − 2·1 = 4 · Schachbrett − → *−4*', 'c eins zwei: zwei mal drei, minus zwei mal eins, ist vier. Vorzeichen minus: minus vier.'), ('c₁₃: Zeile 1, Spalte 3 weg → 2·2 − 4·1 = 0 · Schachbrett + → *0*', 'c eins drei: zwei mal zwei, minus vier mal eins, ist null. Vorzeichen plus: null.'), ('c₂₂: Zeile 2, Spalte 2 weg → 3·3 − 1·1 = 8 · Schachbrett + → *8*', 'c zwei zwei: drei mal drei, minus eins mal eins, ist acht. Vorzeichen plus: acht.'), ('c₂₃: Zeile 2, Spalte 3 weg → 3·2 − 2·1 = 4 · Schachbrett − → *−4*', 'c zwei drei: drei mal zwei, minus zwei mal eins, ist vier. Vorzeichen minus: minus vier.'), ('c₃₃: Zeile 3, Spalte 3 weg → 3·4 − 2·2 = 8 · Schachbrett + → *8*', 'c drei drei: drei mal vier, minus zwei mal zwei, ist acht. Vorzeichen plus: acht.'), ('Spiegeln: c₂₁ = c₁₂ · c₃₁ = c₁₃ · c₃₂ = c₂₃', 'Die drei unteren Einträge spiegelst du einfach von oben an der Diagonale.')]), ('Aufgabe 1 C: die Inverse', [('C′ = C, weil C *symmetrisch* ist.', 'Teil c. Transponieren ändert hier nichts, weil C symmetrisch ist.'), ('A⁻¹ = C′ / 16: 8/16 = ½ · −4/16 = −¼ · 0/16 = 0', 'Dann jeden Eintrag durch sechzehn teilen. Acht durch sechzehn ist ein halb, minus vier durch sechzehn ist minus ein Viertel, null bleibt null.'), ('Probe mit A: Zeile 1 · Spalte 1 = 3·½ + 2·(−¼) + 1·0 = 1,5 − 0,5 = *1* ✓', 'Probe mit A: Zeile eins von A mal Spalte eins der Inversen. Drei mal ein halb ist eins Komma fünf, zwei mal minus ein Viertel ist minus null Komma fünf, eins mal null ist null. Zusammen eins.'), ('Zeile 1 · Spalte 2 = 3·(−¼) + 2·½ + 1·(−¼) = −¾ + 1 − ¼ = *0* ✓', 'Zeile eins mal Spalte zwei: minus drei Viertel plus eins minus ein Viertel. Ergibt null. Passt.'), ('→ *A · A⁻¹ = I* ✓', 'Alle anderen Einträge gehen genauso auf.')]), ('Aufgabe 2: die Aufgabenstellung', [('Aufgabe 2: Gesucht ist der *Lösungsvektor x*.', 'Aufgabe zwei: Gesucht ist der Lösungsvektor x.'), ('Weg: x = *A⁻¹ · b* – erst die Inverse, dann mal b.', 'Der Weg steht schon da: x ist die Inverse mal b. Also zuerst die Inverse wie im Beispiel, dann mal b.'), ('A ist *nicht symmetrisch* → das Transponieren zählt.', 'A ist diesmal nicht symmetrisch. Das Transponieren wird also wichtig.')]), ('Aufgabe 2: die Determinante', [('↘ blau: 4·1·6 = 24 · 0·2·8 = 0 · 2·0·2 = 0 → *24*', 'Sarrus. Blau: vier mal eins mal sechs ist vierundzwanzig. Die anderen zwei blauen Diagonalen treffen eine Null und fallen weg.'), ('↙ orange: 2·1·8 = 16 · 4·2·2 = 16 · 0·0·6 = 0 → *32*', 'Orange: zwei mal eins mal acht ist sechzehn, vier mal zwei mal zwei ist sechzehn, die dritte trifft eine Null. Zusammen zweiunddreißig.'), ('det A = 24 − 32 = *−8 ≠ 0* → A⁻¹ existiert.', 'Vierundzwanzig minus zweiunddreißig ist minus acht. Nicht null, also gibt es die Inverse.')]), ('Aufgabe 2: die Kofaktormatrix', [('Alle *neun* Kofaktoren – hier hilft keine Symmetrie.', 'Jetzt alle neun Kofaktoren, hier hilft keine Symmetrie. Achte auf die Farben: blau mal blau, minus orange mal orange.'), ('c₁₁: Zeile 1, Spalte 1 weg → 1·6 − 2·2 = 2 · Schachbrett + → *2*', 'c eins eins: eins mal sechs, minus zwei mal zwei, ist zwei. Vorzeichen plus: zwei.'), ('c₁₂: Zeile 1, Spalte 2 weg → 0·6 − 2·8 = −16 · Schachbrett − → *16*', 'c eins zwei: null mal sechs, minus zwei mal acht, ist minus sechzehn. Vorzeichen minus, minus mal minus: sechzehn.'), ('c₁₃: Zeile 1, Spalte 3 weg → 0·2 − 1·8 = −8 · Schachbrett + → *−8*', 'c eins drei: null mal zwei, minus eins mal acht, ist minus acht. Vorzeichen plus: minus acht.'), ('c₂₁: Zeile 2, Spalte 1 weg → 0·6 − 2·2 = −4 · Schachbrett − → *4*', 'c zwei eins: null mal sechs, minus zwei mal zwei, ist minus vier. Vorzeichen minus, minus mal minus: vier.'), ('c₂₂: Zeile 2, Spalte 2 weg → 4·6 − 2·8 = 8 · Schachbrett + → *8*', 'c zwei zwei: vier mal sechs, minus zwei mal acht, ist acht. Vorzeichen plus: acht.'), ('c₂₃: Zeile 2, Spalte 3 weg → 4·2 − 0·8 = 8 · Schachbrett − → *−8*', 'c zwei drei: vier mal zwei, minus null mal acht, ist acht. Vorzeichen minus: minus acht.'), ('c₃₁: Zeile 3, Spalte 1 weg → 0·2 − 2·1 = −2 · Schachbrett + → *−2*', 'c drei eins: null mal zwei, minus zwei mal eins, ist minus zwei. Vorzeichen plus: minus zwei.'), ('c₃₂: Zeile 3, Spalte 2 weg → 4·2 − 2·0 = 8 · Schachbrett − → *−8*', 'c drei zwei: vier mal zwei, minus zwei mal null, ist acht. Vorzeichen minus: minus acht.'), ('c₃₃: Zeile 3, Spalte 3 weg → 4·1 − 0·0 = 4 · Schachbrett + → *4*', 'c drei drei: vier mal eins, minus null mal null, ist vier. Vorzeichen plus: vier.')]), ('Aufgabe 2: transponieren und teilen', [('C′: Zeile 1 von C (2 16 −8) wird *Spalte 1* – usw.', 'Transponieren: Die erste Zeile, zwei, sechzehn, minus acht, wird zur ersten Spalte. Genauso die zweite und die dritte Zeile.'), ('Ohne Transponieren wäre hier *jede Zeile* der Inversen falsch.', 'Ohne diesen Schritt wäre hier jede Zeile der Inversen falsch.'), ('A⁻¹ = C′ / (−8): 2/(−8) = −¼ · 16/(−8) = −2 · −8/(−8) = 1 …', 'Dann durch minus acht teilen. Zwei durch minus acht ist minus ein Viertel, sechzehn durch minus acht ist minus zwei, minus acht durch minus acht ist eins. Das Minus dreht jedes Vorzeichen um.')]), ('Aufgabe 2: x berechnen und Probe', [('x₁ = Zeile 1 von A⁻¹ · b = (−¼)·0 + (−½)·8 + ¼·4 = 0 − 4 + 1 = *−3*', 'Jetzt x gleich Inverse mal b, Zeile mal Spalte. x eins: minus ein Viertel mal null ist null, minus ein halb mal acht ist minus vier, ein Viertel mal vier ist eins. Zusammen minus drei.'), ('x₂ = (−2)·0 + (−1)·8 + 1·4 = *−4*', 'x zwei: null, minus acht, plus vier. Ergibt minus vier.'), ('x₃ = 1·0 + 1·8 + (−½)·4 = 8 − 2 = *6*', 'x drei: null, plus acht, minus zwei. Ergibt sechs.'), ('Probe mit A: Zeile 1 · x = 4·(−3) + 0·(−4) + 2·6 = −12 + 12 = *0* = b₁ ✓', 'Zur Probe nimmst du die ursprüngliche Matrix A, unten eingeblendet, mal x. Zeile eins: vier mal minus drei ist minus zwölf, null mal minus vier ist null, zwei mal sechs ist zwölf. Zusammen null, genau der erste Eintrag von b.'), ('Zeile 2 · x = 0·(−3) + 1·(−4) + 2·6 = *8* = b₂ ✓', 'Zeile zwei: null, minus vier, plus zwölf. Ergibt acht.'), ('Zeile 3 · x = 8·(−3) + 2·(−4) + 6·6 = −24 − 8 + 36 = *4* = b₃ ✓', 'Zeile drei: minus vierundzwanzig, minus acht, plus sechsunddreißig. Ergibt vier. Es kommt also wieder b heraus, x stimmt.')]), ('Aufgabe 3 A: die Aufgabenstellung', [('Aufgabe 3 A: *Gibt es* eine eindeutige Lösung?', 'Aufgabe drei a fragt zuerst: Gibt es überhaupt eine eindeutige Lösung?'), ('Nur *falls ja*: mit Gauß-Jordan berechnen.', 'Nur falls ja, sollst du sie mit Gauß-Jordan berechnen.'), ('Also zuerst: *det A*.', 'Also kommt zuerst die Determinante.')]), ('Aufgabe 3 A: die Determinante', [('↘ blau: 4·3·4 = 48 · 8·1·6 = 48 · 2·1·14 = 28 → *124*', 'Blau: vier mal drei mal vier ist achtundvierzig, acht mal eins mal sechs ist achtundvierzig, zwei mal eins mal vierzehn ist achtundzwanzig. Zusammen hundertvierundzwanzig.'), ('↙ orange: 2·3·6 = 36 · 4·1·14 = 56 · 8·1·4 = 32 → *124*', 'Orange: zwei mal drei mal sechs ist sechsunddreißig, vier mal eins mal vierzehn ist sechsundfünfzig, acht mal eins mal vier ist zweiunddreißig. Zusammen auch hundertvierundzwanzig.'), ('det A = 124 − 124 = *0* → *keine* eindeutige Lösung.', 'Hundertvierundzwanzig minus hundertvierundzwanzig ist null. Damit gibt es keine eindeutige Lösung, und Gauß-Jordan entfällt.')]), ('Aufgabe 3 A: warum det = 0?', [('Warum 0? Die *Zeilen* hängen voneinander ab.', 'Warum ist die Determinante null? Weil die Zeilen voneinander abhängen.'), ('Spalte für Spalte: *Zeile I* + 2 · *Zeile II* = *Zeile III*', 'Nimm Zeile eins, blau, und addiere zweimal Zeile zwei, orange. Erste Spalte: vier plus zwei mal eins ist sechs. Zweite Spalte: acht plus zwei mal drei ist vierzehn. Dritte Spalte: zwei plus zwei mal eins ist vier. Das ist genau Zeile drei, lila.'), ('Rechte Seite genauso: *4* + 2 · *3* = 10 – aber b₃ = *7*', 'Jetzt dieselbe Kombination rechts beim Vektor b: vier plus zwei mal drei ist zehn. In Zeile drei steht aber sieben.'), ('III − I − 2·II: links *0*, rechts 7 − 10 = *−3* → 0 = −3', 'Rechnet man Zeile drei minus Zeile eins minus zweimal Zeile zwei, bleibt links null und rechts minus drei. Null gleich minus drei ist ein Widerspruch.'), ('→ *gar keine* Lösung · rg A = 2 < rg (A|b) = 3', 'Das System hat also gar keine Lösung. In der Sprache der Ränge: A hat Rang zwei, die erweiterte Matrix Rang drei.')]), ('Aufgabe 3 B: die Aufgabenstellung', [('Aufgabe 3 B: wieder erst *ob*, dann *Gauß-Jordan*.', 'Bei drei b genauso: erst prüfen, dann mit Gauß-Jordan rechnen.'), ('Gegeben: A (2×2) und *b = (6; 4)*.', 'Diesmal ist A nur zwei mal zwei, und b ist sechs und vier.')]), ('Aufgabe 3 B: Gauß-Jordan', [('det A = 1·6 − 4·2 = 6 − 8 = *−2 ≠ 0* → eindeutig lösbar.', 'Zuerst die Determinante: eins mal sechs minus vier mal zwei ist minus zwei. Nicht null, also eindeutig lösbar.'), ('Start: *(A | I)* – Ziel: links *I*, dann steht rechts *A⁻¹*.', 'Für Gauß-Jordan schreibst du A und daneben die Einheitsmatrix. Du formst so lange um, bis links die Einheitsmatrix steht. Dann steht rechts die Inverse.'), ('*II − 2·I*: 2−2·1 = 0 · 6−2·4 = −2 · 0−2·1 = −2 · 1−2·0 = 1', 'Unter der Eins soll eine Null entstehen. Dafür rechnest du Zeile zwei minus zweimal Zeile eins, über die ganze Zeile: zwei minus zwei ist null, sechs minus acht ist minus zwei, null minus zwei ist minus zwei, eins minus null ist eins.'), ('*II : (−2)*: 0 · 1 · 1 · −½', 'Auf der Diagonale soll eine Eins stehen. Also teilst du Zeile zwei durch minus zwei: null, eins, eins und minus ein halb.'), ('*I − 4·II*: 1−4·0 = 1 · 4−4·1 = 0 · 1−4·1 = −3 · 0−4·(−½) = 2', 'Über der Eins soll auch eine Null stehen: Zeile eins minus viermal Zeile zwei. Eins minus null ist eins, vier minus vier ist null, eins minus vier ist minus drei, null minus vier mal minus ein halb ist plus zwei.'), ('Links *I* → rechts *A⁻¹ = (−3 2; 1 −½)*', 'Links steht jetzt die Einheitsmatrix. Rechts liest du die Inverse ab.')]), ('Aufgabe 3 B: x und Probe', [('x₁ = (−3)·6 + 2·4 = −18 + 8 = *−10*', 'Jetzt die Inverse mal b, mit b gleich sechs und vier. x eins: minus drei mal sechs ist minus achtzehn, zwei mal vier ist acht. Zusammen minus zehn.'), ('x₂ = 1·6 + (−½)·4 = 6 − 2 = *4*', 'x zwei: eins mal sechs ist sechs, minus ein halb mal vier ist minus zwei. Ergibt vier.'), ('Probe mit A: 1·(−10) + 4·4 = *6* = b₁ ✓', 'Probe mit A: eins mal minus zehn plus vier mal vier ist sechs.'), ('2·(−10) + 6·4 = *4* = b₂ ✓', 'Zwei mal minus zehn plus sechs mal vier ist vier. Beides stimmt mit b überein.')]), ('Aufgabe 3 C: die Aufgabenstellung', [('Aufgabe 3 C: diesmal mit der *Determinantenformel*.', 'Bei drei c ist das Werkzeug die Determinantenformel, also der Weg aus dem Beispiel.'), ('det · Kofaktoren · transponieren · teilen · *mal b*', 'Erst prüfen, dann Kofaktoren, transponieren, teilen und mal b.')]), ('Aufgabe 3 C: die Determinante', [('↘ blau: 1·3·8 = 24 · 2·7·3 = 42 · 5·2·4 = 40 → *106*', 'Blau: eins mal drei mal acht ist vierundzwanzig, zwei mal sieben mal drei ist zweiundvierzig, fünf mal zwei mal vier ist vierzig. Zusammen hundertsechs.'), ('↙ orange: 5·3·3 = 45 · 1·7·4 = 28 · 2·2·8 = 32 → *105*', 'Orange: fünf mal drei mal drei ist fünfundvierzig, eins mal sieben mal vier ist achtundzwanzig, zwei mal zwei mal acht ist zweiunddreißig. Zusammen hundertfünf.'), ('det A = 106 − 105 = *1* → durch 1 teilen ändert nichts: *A⁻¹ = C′*', 'Hundertsechs minus hundertfünf ist eins. Das ist ein Geschenk: Durch eins teilen ändert nichts. Die Inverse ist einfach die transponierte Kofaktormatrix.')]), ('Aufgabe 3 C: die Kofaktormatrix', [('c₁₁: Zeile 1, Spalte 1 weg → 3·8 − 7·4 = −4 · Schachbrett + → *−4*', 'c eins eins: drei mal acht, minus sieben mal vier, ist minus vier. Vorzeichen plus: minus vier.'), ('c₁₂: Zeile 1, Spalte 2 weg → 2·8 − 7·3 = −5 · Schachbrett − → *5*', 'c eins zwei: zwei mal acht, minus sieben mal drei, ist minus fünf. Vorzeichen minus, minus mal minus: fünf.'), ('c₁₃: Zeile 1, Spalte 3 weg → 2·4 − 3·3 = −1 · Schachbrett + → *−1*', 'c eins drei: zwei mal vier, minus drei mal drei, ist minus eins. Vorzeichen plus: minus eins.'), ('c₂₁: Zeile 2, Spalte 1 weg → 2·8 − 5·4 = −4 · Schachbrett − → *4*', 'c zwei eins: zwei mal acht, minus fünf mal vier, ist minus vier. Vorzeichen minus, minus mal minus: vier.'), ('c₂₂: Zeile 2, Spalte 2 weg → 1·8 − 5·3 = −7 · Schachbrett + → *−7*', 'c zwei zwei: eins mal acht, minus fünf mal drei, ist minus sieben. Vorzeichen plus: minus sieben.'), ('c₂₃: Zeile 2, Spalte 3 weg → 1·4 − 2·3 = −2 · Schachbrett − → *2*', 'c zwei drei: eins mal vier, minus zwei mal drei, ist minus zwei. Vorzeichen minus, minus mal minus: zwei.'), ('c₃₁: Zeile 3, Spalte 1 weg → 2·7 − 5·3 = −1 · Schachbrett + → *−1*', 'c drei eins: zwei mal sieben, minus fünf mal drei, ist minus eins. Vorzeichen plus: minus eins.'), ('c₃₂: Zeile 3, Spalte 2 weg → 1·7 − 5·2 = −3 · Schachbrett − → *3*', 'c drei zwei: eins mal sieben, minus fünf mal zwei, ist minus drei. Vorzeichen minus, minus mal minus: drei.'), ('c₃₃: Zeile 3, Spalte 3 weg → 1·3 − 2·2 = −1 · Schachbrett + → *−1*', 'c drei drei: eins mal drei, minus zwei mal zwei, ist minus eins. Vorzeichen plus: minus eins.')]), ('Aufgabe 3 C: transponieren', [('C′: Zeilen von C werden *Spalten* – und weil det = 1: *A⁻¹ = C′*', 'Transponieren: Zeile eins von C wird Spalte eins, und so weiter. Weil die Determinante eins ist, ist das schon die Inverse.')]), ('Aufgabe 3 C: x und Probe', [('x₁ = (−4)·1 + 4·3 + (−1)·13 = *−5*', 'Jetzt mal b, Zeile mal Spalte. x eins: minus vier, plus zwölf, minus dreizehn. Zusammen minus fünf.'), ('x₂ = 5·1 + (−7)·3 + 3·13 = *23*', 'x zwei: fünf, minus einundzwanzig, plus neununddreißig. Zusammen dreiundzwanzig.'), ('x₃ = (−1)·1 + 2·3 + (−1)·13 = *−8*', 'x drei: minus eins, plus sechs, minus dreizehn. Zusammen minus acht.'), ('Probe Zeile 1 = 1·(−5) + 2·23 + 5·(−8) = *1* = b₁ ✓', 'Probe mit A, unten eingeblendet. Zeile eins: minus fünf, plus sechsundvierzig, minus vierzig. Zusammen eins.'), ('Probe Zeile 2 = 2·(−5) + 3·23 + 7·(−8) = *3* = b₂ ✓', 'Zeile zwei: minus zehn, plus neunundsechzig, minus sechsundfünfzig. Zusammen drei.'), ('Probe Zeile 3 = 3·(−5) + 4·23 + 8·(−8) = *13* = b₃ ✓', 'Zeile drei: minus fünfzehn, plus zweiundneunzig, minus vierundsechzig. Zusammen dreizehn. Also kommt genau b heraus.')]), ('Aufgabe 4: die Aufgabenstellung', [('Zwei Wasserquellen: Quelle 1 *salzarm*, Quelle 2 billig, aber *salzig*.', 'In Aufgabe vier gibt es zwei Wasserquellen. Quelle eins hat kaum Salz, Quelle zwei ist billig, aber viel zu salzig.'), ('Gesucht: Mischverhältnis x mit *0,08 % Salz* und *pH 7,0*.', 'Gesucht ist ein Mischverhältnis x, so dass die Mischung null Komma null acht Prozent Salz und den pH-Wert sieben hat.'), ('A) Gleichungen · B) A x = b · C) lösen · D) bewerten', 'Dazu sollst du die Gleichungen aufstellen, in Matrixform bringen, mit der Determinantenformel lösen und das Ergebnis bewerten.')]), ('Aufgabe 4 A und B: das System aufstellen', [('x₁ = Anteil *Quelle 1* · x₂ = Anteil *Quelle 2*', 'x eins ist der Anteil aus Quelle eins, x zwei der Anteil aus Quelle zwei.'), ('Zeile 1 Salz: 0,02 x₁ + 2,0 x₂ = *0,08*', 'Zeile eins ist der Salzgehalt: null Komma null zwei mal x eins plus zwei Komma null mal x zwei soll null Komma null acht ergeben.'), ('Zeile 2 pH: 6,5 x₁ + 8,1 x₂ = *7,0*', 'Zeile zwei genauso mit den pH-Werten: sechs Komma fünf mal x eins plus acht Komma eins mal x zwei gleich sieben. Das ist Teil a.'), ('B) Zahlen vor x → *A* · Zielwerte → *b*', 'Für Teil b schreibst du die Zahlen vor x eins und x zwei in die Matrix A und die Zielwerte in den Vektor b.')]), ('Aufgabe 4 C: woher kommt die 2×2-Formel?', [('det A = 0,02·8,1 − 2,0·6,5 = 0,162 − 13 = *−12,838*', 'Teil c. Zuerst die Determinante: null Komma null zwei mal acht Komma eins ist null Komma eins sechs zwei. Minus zwei mal sechs Komma fünf, also dreizehn. Ergibt minus zwölf Komma acht drei acht.'), ('Was wird berechnet? *A⁻¹* – denn aus A x = b folgt *x = A⁻¹ · b*.', 'Was berechnen wir eigentlich? Wenn A mal x gleich b ist, dann ist x gleich Inverse mal b. Also brauchen wir zuerst die Inverse.'), ('Gleiche Formel wie bei 3×3: A⁻¹ = C′ / det – nach dem Abdecken bleibt *eine Zahl*.', 'Die Inverse kommt aus derselben Formel wie bei drei mal drei. Bei zwei mal zwei bleibt nach dem Abdecken von Zeile und Spalte nur eine einzige Zahl übrig.'), ('c₁₁ = *+d* · c₁₂ = *−c* · c₂₁ = *−b* · c₂₂ = *+a*', 'Für c eins eins bleibt d übrig, Vorzeichen plus. Für c eins zwei bleibt c, Vorzeichen minus. Für c zwei eins bleibt b, mit minus. Und für c zwei zwei bleibt a, mit plus.'), ('Transponieren → C′ = (d −b; −c a): *Diagonale getauscht*, Nebendiagonale *Minus*', 'Jetzt transponieren. Dabei tauschen nur die beiden Minus-Einträge die Plätze. Heraus kommt: d und a haben auf der Diagonale getauscht, und die Nebendiagonale hat ein Minus. Genau das ist die Kurzregel.'), ('Kontrolle: A · C′ = (ad−bc 0; 0 ad−bc) = *det · I* → durch det teilen → *I*', 'Warum stimmt das? A mal diese Matrix ergibt auf der Diagonale a mal d minus b mal c, also die Determinante, und daneben null. Teilst du noch durch die Determinante, steht dort die Einheitsmatrix.')]), ('Aufgabe 4 C: mit unseren Zahlen', [('A⁻¹ = 1/(−12,838) · (8,1 −2,0; −6,5 0,02)', 'Mit unseren Zahlen: acht Komma eins und null Komma null zwei tauschen die Plätze, zwei Komma null und sechs Komma fünf bekommen ein Minus. Das Ganze geteilt durch minus zwölf Komma acht drei acht.'), ('x₁ = (8,1·0,08 − 2,0·7,0) / (−12,838) = −13,352 / −12,838 ≈ *1,040*', 'Dann mal b. x eins: acht Komma eins mal null Komma null acht minus zwei mal sieben, das ist minus dreizehn Komma drei fünf zwei. Geteilt durch minus zwölf Komma acht drei acht ergibt etwa eins Komma null vier.'), ('x₂ = (−6,5·0,08 + 0,02·7,0) / (−12,838) = −0,38 / −12,838 ≈ *0,030*', 'x zwei: minus sechs Komma fünf mal null Komma null acht plus null Komma null zwei mal sieben, das ist minus null Komma drei acht. Geteilt durch die Determinante etwa null Komma null drei.')]), ('Aufgabe 4 D: lohnt sich Quelle 2?', [('Verhältnis x₁ : x₂ ≈ 1,040 : 0,030 ≈ *35 : 1*', 'Teil d. Das Verhältnis: eins Komma null vier zu null Komma null drei, das sind etwa fünfunddreißig zu eins.'), ('Auf 35 Teile Quelle 1 kommt nur *1 Teil* Quelle 2.', 'Auf fünfunddreißig Teile aus Quelle eins kommt also nur ein Teil aus Quelle zwei.'), ('→ spart *kaum* teures Wasser – lohnt sich eher *nicht*.', 'Damit spart man kaum teures Wasser. Quelle zwei zu verwenden lohnt sich eher nicht.')]), ('Knobelaufgabe: die Aufgabenstellung', [('Knobelaufgabe: eine 4×4-Matrix mit *Wurzeln*.', 'Die Knobelaufgabe: eine vier mal vier Matrix mit Wurzeln.'), ('A) invertierbar? · B) A⁻¹ bilden und ihre *Eigenschaft* nennen', 'Du sollst prüfen, ob sie invertierbar ist, die Inverse bilden und sagen, welche Eigenschaft sie hat.'), ('Hinweis: *geschickt* rechnen – Sarrus geht bei 4×4 *nicht*.', 'Der Hinweis verrät: Mit dem richtigen Trick sparst du viel Zeit. Sarrus geht bei vier mal vier gar nicht, und Gauß-Jordan mit Wurzeln dauert ewig.')]), ('Knobel: der Trick mit dem Skalarprodukt', [('Idee: Probier *A′* als Inverse – rechne *A · A′*.', 'Die Idee: Wir vermuten, dass die Transponierte schon die Inverse ist, und rechnen A mal A strich aus.'), ('Spalte j von A′ = *Zeile j von A*.', 'Beim Transponieren werden die Zeilen von A zu den Spalten von A strich. Spalte j von A strich ist also Zeile j von A.'), ('→ Eintrag (i, j) von A·A′ = *Zeile i · Zeile j* – ein Skalarprodukt', 'Deshalb ist jeder Eintrag von A mal A strich ein Skalarprodukt zweier Zeilen von A: Eintrag i j ist Zeile i mal Zeile j.'), ('Diagonale: Zeile · *sich selbst* = Länge² → muss *1* sein.', 'Auf der Diagonale wird eine Zeile mit sich selbst multipliziert. Das ist ihre Länge zum Quadrat. Dort muss eine Eins herauskommen.'), ('Daneben: zwei *verschiedene* Zeilen → muss *0* sein = *senkrecht*.', 'Neben der Diagonale treffen zwei verschiedene Zeilen aufeinander. Dort muss null herauskommen. Ein Skalarprodukt von null heißt: Die beiden Zeilen stehen senkrecht aufeinander.')]), ('Knobel: nachrechnen', [('Z1·Z1 = ¼+¼+¼+¼ = *1* · Z3·Z3 = ½+½+0+0 = *1*', 'Jetzt rechnen. Zeile eins mal sich selbst: viermal ein halb zum Quadrat, also viermal ein Viertel. Eins. Zeile drei mit sich selbst: ein halb plus ein halb. Auch eins. Die Zeilen zwei und vier gehen genauso.'), ('Z1·Z2 = ¼ + ¼ − ¼ − ¼ = *0*', 'Zeile eins mal Zeile zwei: ein Viertel plus ein Viertel minus ein Viertel minus ein Viertel. Null.'), ('Z1·Z3 = ½·1/√2 − ½·1/√2 + 0 + 0 = *0*', 'Zeile eins mal Zeile drei: Die beiden Wurzelterme heben sich gegenseitig auf. Wieder null.'), ('Z3·Z4 = 0 + 0 + 0 + 0 = *0* – so ist *jedes Paar* 0.', 'Zeile drei mal Zeile vier: Wo die eine eine Zahl hat, hat die andere eine Null. Auch null. So ergibt jedes Paar null.'), ('A · A′ = *I* → A⁻¹ = *A′* → A ist *invertierbar*', 'Damit ist A mal A strich die Einheitsmatrix. Genau so ist die Inverse definiert. Also ist A invertierbar, und die Inverse ist einfach die Transponierte.'), ('Eigenschaft: A⁻¹ = A′ ist *orthogonal* – Zeilen Länge 1, paarweise senkrecht.', 'Die gesuchte Eigenschaft: Auch die Inverse ist orthogonal. Ihre Zeilen haben die Länge eins und stehen senkrecht aufeinander.')]), ('Altklausur: die Aufgabenstellung', [('Altklausur: *zwei* Systeme, A x = b und B x = b.', 'In der Altklausuraufgabe gibt es zwei Gleichungssysteme mit demselben b.'), ('Erst: *lösbar*? Dann Lösung *nur* über die Kofaktormatrix.', 'Erst prüfst du, ob sie lösbar sind. Dann löst du sie, und zwar nur über die Kofaktormatrix. Andere Wege geben keine Punkte.'), ('A und B unterscheiden sich nur in *Zeile 3*.', 'Achte darauf: A und B unterscheiden sich nur in der dritten Zeile.')]), ('Altklausur: det A', [('↘ blau: 1·2·3 = 6 · 2·1·3 = 6 · 1·2·2 = 4 → *16*', 'Zuerst die Lösbarkeit. Für A blau: eins mal zwei mal drei ist sechs, zwei mal eins mal drei ist sechs, eins mal zwei mal zwei ist vier. Zusammen sechzehn.'), ('↙ orange: 1·2·3 = 6 · 1·1·2 = 2 · 2·2·3 = 12 → *20*', 'Orange: eins mal zwei mal drei ist sechs, eins mal eins mal zwei ist zwei, zwei mal zwei mal drei ist zwölf. Zusammen zwanzig.'), ('det A = 16 − 20 = *−4 ≠ 0* → Ax = b eindeutig lösbar', 'Sechzehn minus zwanzig ist minus vier. Nicht null, also ist A x gleich b eindeutig lösbar.')]), ('Altklausur: det B', [('↘ blau: 1·2·2 = 4 · 2·1·3 = 6 · 1·2·3 = 6 → *16*', 'Für B blau: eins mal zwei mal zwei ist vier, zwei mal eins mal drei ist sechs, eins mal zwei mal drei ist sechs. Zusammen sechzehn.'), ('↙ orange: 1·2·3 = 6 · 1·1·3 = 3 · 2·2·2 = 8 → *17*', 'Orange: eins mal zwei mal drei ist sechs, eins mal eins mal drei ist drei, zwei mal zwei mal zwei ist acht. Zusammen siebzehn.'), ('det B = 16 − 17 = *−1 ≠ 0* → Bx = b eindeutig lösbar', 'Sechzehn minus siebzehn ist minus eins. Auch B x gleich b ist eindeutig lösbar. Beide Werte kennst du schon aus Übung eins.')]), ('Altklausur: Kofaktormatrix von A', [('c₁₁: Zeile 1, Spalte 1 weg → 2·3 − 1·2 = 4 · Schachbrett + → *4*', 'Jetzt die Kofaktormatrix von A. c eins eins: zwei mal drei, minus eins mal zwei, ist vier. Vorzeichen plus: vier.'), ('c₁₂: Zeile 1, Spalte 2 weg → 2·3 − 1·3 = 3 · Schachbrett − → *−3*', 'c eins zwei: zwei mal drei, minus eins mal drei, ist drei. Vorzeichen minus: minus drei.'), ('c₁₃: Zeile 1, Spalte 3 weg → 2·2 − 2·3 = −2 · Schachbrett + → *−2*', 'c eins drei: zwei mal zwei, minus zwei mal drei, ist minus zwei. Vorzeichen plus: minus zwei.'), ('c₂₁: Zeile 2, Spalte 1 weg → 2·3 − 1·2 = 4 · Schachbrett − → *−4*', 'c zwei eins: zwei mal drei, minus eins mal zwei, ist vier. Vorzeichen minus: minus vier.'), ('c₂₂: Zeile 2, Spalte 2 weg → 1·3 − 1·3 = 0 · Schachbrett + → *0*', 'c zwei zwei: eins mal drei, minus eins mal drei, ist null. Vorzeichen plus: null.'), ('c₂₃: Zeile 2, Spalte 3 weg → 1·2 − 2·3 = −4 · Schachbrett − → *4*', 'c zwei drei: eins mal zwei, minus zwei mal drei, ist minus vier. Vorzeichen minus, minus mal minus: vier.'), ('c₃₁: Zeile 3, Spalte 1 weg → 2·1 − 1·2 = 0 · Schachbrett + → *0*', 'c drei eins: zwei mal eins, minus eins mal zwei, ist null. Vorzeichen plus: null.'), ('c₃₂: Zeile 3, Spalte 2 weg → 1·1 − 1·2 = −1 · Schachbrett − → *1*', 'c drei zwei: eins mal eins, minus eins mal zwei, ist minus eins. Vorzeichen minus, minus mal minus: eins.'), ('c₃₃: Zeile 3, Spalte 3 weg → 1·2 − 2·2 = −2 · Schachbrett + → *−2*', 'c drei drei: eins mal zwei, minus zwei mal zwei, ist minus zwei. Vorzeichen plus: minus zwei.')]), ('Altklausur: Ax = b: transponieren', [('C′: Zeilen von C werden *Spalten*.', 'Zuerst transponieren: Die Zeilen der Kofaktormatrix werden zu Spalten.')]), ('Altklausur: Ax = b: Lösung', [('Zeile 1 = 4·1 + (−4)·4 + 0·2 = *−12*', 'Dann C strich mal b. Zeile eins: vier, minus sechzehn, plus null. Zusammen minus zwölf.'), ('Zeile 2 = (−3)·1 + 0·4 + 1·2 = *−1*', 'Zeile zwei: minus drei, plus null, plus zwei. Zusammen minus eins.'), ('Zeile 3 = (−2)·1 + 4·4 + (−2)·2 = *10*', 'Zeile drei: minus zwei, plus sechzehn, minus vier. Zusammen zehn.'), ('x = (−12; −1; 10) / (−4) = *(3; 0,25; −2,5)*', 'Jetzt noch durch die Determinante, minus vier: Minus zwölf durch minus vier ist drei, minus eins durch minus vier ist null Komma zwei fünf, zehn durch minus vier ist minus zwei Komma fünf. Das ist genau die Lösung aus Übung eins.'), ('Probe Zeile 1: 1·3 + 2·0,25 + 1·(−2,5) = *1* ✓', 'Probe mit A: Zeile eins: drei, plus null Komma fünf, minus zwei Komma fünf. Ergibt eins.'), ('Probe Zeile 2: 2·3 + 2·0,25 + 1·(−2,5) = *4* ✓', 'Zeile zwei: sechs, plus null Komma fünf, minus zwei Komma fünf. Ergibt vier.'), ('Probe Zeile 3: 3·3 + 2·0,25 + 3·(−2,5) = *2* ✓', 'Zeile drei: neun, plus null Komma fünf, minus sieben Komma fünf. Ergibt zwei.')]), ('Altklausur: Kofaktormatrix von B', [('Zeile 3 gestrichen → *A und B gleich* → c₃₁, c₃₂, c₃₃ *wie bei A*', 'Jetzt B. Bei c drei eins, c drei zwei und c drei drei wird Zeile drei gestrichen. Genau die Zeile, in der sich A und B unterscheiden. Diese drei Kofaktoren sind also dieselben wie bei A.'), ('c₁₁: Zeile 1, Spalte 1 weg → 2·2 − 1·3 = 1 · Schachbrett + → *1*', 'c eins eins: zwei mal zwei, minus eins mal drei, ist eins. Vorzeichen plus: eins.'), ('c₁₂: Zeile 1, Spalte 2 weg → 2·2 − 1·3 = 1 · Schachbrett − → *−1*', 'c eins zwei: zwei mal zwei, minus eins mal drei, ist eins. Vorzeichen minus: minus eins.'), ('c₁₃: Zeile 1, Spalte 3 weg → 2·3 − 2·3 = 0 · Schachbrett + → *0*', 'c eins drei: zwei mal drei, minus zwei mal drei, ist null. Vorzeichen plus: null.'), ('c₂₁: Zeile 2, Spalte 1 weg → 2·2 − 1·3 = 1 · Schachbrett − → *−1*', 'c zwei eins: zwei mal zwei, minus eins mal drei, ist eins. Vorzeichen minus: minus eins.'), ('c₂₂: Zeile 2, Spalte 2 weg → 1·2 − 1·3 = −1 · Schachbrett + → *−1*', 'c zwei zwei: eins mal zwei, minus eins mal drei, ist minus eins. Vorzeichen plus: minus eins.'), ('c₂₃: Zeile 2, Spalte 3 weg → 1·3 − 2·3 = −3 · Schachbrett − → *3*', 'c zwei drei: eins mal drei, minus zwei mal drei, ist minus drei. Vorzeichen minus, minus mal minus: drei.')]), ('Altklausur: Bx = b: transponieren', [('C′: Zeilen von C werden *Spalten*.', 'Zuerst transponieren: Die Zeilen der Kofaktormatrix werden zu Spalten.')]), ('Altklausur: Bx = b: Lösung', [('Zeile 1 = 1·1 + (−1)·4 + 0·2 = *−3*', 'Dann C strich mal b. Zeile eins: eins, minus vier, plus null. Zusammen minus drei.'), ('Zeile 2 = (−1)·1 + (−1)·4 + 1·2 = *−3*', 'Zeile zwei: minus eins, minus vier, plus zwei. Zusammen minus drei.'), ('Zeile 3 = 0·1 + 3·4 + (−2)·2 = *8*', 'Zeile drei: null, plus zwölf, minus vier. Zusammen acht.'), ('x = (−3; −3; 8) / (−1) = *(3; 3; −8)*', 'Jetzt noch durch minus eins teilen, also alle Vorzeichen umdrehen: drei, drei, minus acht. Auch das passt zu Übung eins.'), ('Probe Zeile 1: 1·3 + 2·3 + 1·(−8) = *1* ✓', 'Probe mit B: Zeile eins: drei, plus sechs, minus acht. Ergibt eins.'), ('Probe Zeile 2: 2·3 + 2·3 + 1·(−8) = *4* ✓', 'Zeile zwei: sechs, plus sechs, minus acht. Ergibt vier.'), ('Probe Zeile 3: 3·3 + 3·3 + 2·(−8) = *2* ✓', 'Zeile drei: neun, plus neun, minus sechzehn. Ergibt zwei.')]), ('Merke', [('1. *det A* – ist sie 0, gibt es *keine* Inverse.', 'Merke: Zuerst immer die Determinante. Ist sie null, gibt es keine Inverse.'), ('2. c_ij: *Zeile i + Spalte j* abdecken, 2×2-det, *Schachbrett*.', 'Für jeden Kofaktor: Zeile und Spalte abdecken, die kleine Determinante rechnen, Vorzeichen aus dem Schachbrett.'), ('3. C *transponieren*, durch det teilen.', 'Dann die Kofaktormatrix transponieren und durch die Determinante teilen.'), ('4. *Probe* mit A: A · x = b bzw. A · A⁻¹ = I.', 'Und am Ende die Probe mit der ursprünglichen Matrix. Sie findet fast jeden Vorzeichenfehler.')]), ('Selbst üben', [('Rechne alles in deiner GoodNotes-Datei „Übung 02 ausführlich“ nach.', 'Rechne jetzt alles selbst in deiner GoodNotes-Datei nach. Die Schablonen sind schon vorgezeichnet.')]), ('Teil 1 geschafft', [('Weiter in *Teil 2*: Aufgabe 3 C, Aufgabe 4, Knobel und Altklausur.', '')])]
